mapper.select:
SELECT rt.id, rt.task_no, rt.event_id, rt.assignee_id, rt.dispatcher_id, rt.status, rt.priority, rt.dispatch_at, rt.accept_at, rt.arrive_at, rt.complete_at, rt.result_type, rt.result_note, rt.result_photo_urls, rt.created_at, rt.updated_at, rt.deleted, rt.task_location, u1.real_name AS assignee_name, u1.phone AS assignee_phone, u2.real_name AS dispatcher_name, ae.event_no AS event_no, ae.snapshot_url AS snapshot_url, ae.source_device_id AS source_device_id, ae.confidence AS confidence, ae.alert_type AS alert_type, d.device_name AS source_device_name, d.device_code AS source_device_code FROM rescue_task rt LEFT JOIN sys_user u1 ON rt.assignee_id = u1.id LEFT JOIN sys_user u2 ON rt.dispatcher_id = u2.id LEFT JOIN alert_event ae ON rt.event_id = ae.id LEFT JOIN device d ON ae.source_device_id = d.id WHERE rt.deleted = 0
AND rt.status = #{status}
AND rt.assignee_id = #{assigneeId}
AND rt.event_id = #{eventId}
ORDER BY rt.created_at DESC
